T("A Suite look, font, minimum height and position for Blizzard dialogs, marked resurrection offers, the item quality written on loot toasts and gold-framed money toasts.", "Оформление, шрифт, минимальная высота и положение Suite для диалогов Blizzard, отмеченные предложения воскрешения, качество предмета в уведомлениях о добыче и золотая рамка у уведомлений о деньгах.")
T("A bar cannot attach to itself.", "Панель не может прикрепиться к самой себе.")
T("A bar cannot send cooldowns to itself.", "Панель не может отправлять восстановления самой себе.")
T("A cinematic Suite screen with your character while you are AFK. Move or use /afk to return.", "Кинематографичный экран Suite с вашим персонажем, пока вы AFK. Начните движение или введите /afk, чтобы вернуться.")
T("A class in your group can provide this buff.", "Один из классов в группе может дать этот положительный эффект.")
T("A clean minimap in its own frame: size, shape, border, zoom, Blizzard buttons, an addon button drawer and information texts. Blizzard's minimap buttons keep working.", "Аккуратная миникарта в отдельном фрейме: размер, форма, рамка, масштаб, кнопки Blizzard, ящик кнопок аддонов и информационные тексты. Кнопки миникарты Blizzard продолжают работать.")
T("A click-through surface follows each Blizzard chat window. Blizzard and MSUF Edit Mode keep their normal move and resize controls.", "За каждым окном чата Blizzard следует подложка, пропускающая клики. Режимы редактирования Blizzard и MSUF сохраняют обычные элементы перемещения и изменения размера.")
T("A colored plate sits behind the map and its border. Padding extends it beyond the map edge.", "За картой и ее рамкой находится цветная подложка. Отступ расширяет ее за край карты.")
T("A compact, movable history of your recent successful spells.", "Компактная перемещаемая история последних успешно примененных заклинаний.")
T("A frame-rate readout can sit below the strip or on its own, placed in MSUF Edit Mode. The MSUF Suite FPS key binding shows or hides it for this session, in combat too; a new choice here replaces that session switch.", "Счетчик кадров можно разместить под полосой или отдельно, в режиме редактирования MSUF. Клавиша FPS из MSUF Suite показывает или скрывает его на эту сессию, в том числе в бою; новый выбор здесь заменяет этот переключатель сессии.")
T("A movable strip for critical strike, haste, mastery and versatility.", "Подвижная полоска для критического удара, скорости, искусности и универсальности.")
T("A movable summary after a Mythic+ run or raid boss kill.", "Перемещаемый итог после забега эпохального+ или победы над боссом рейда.")
T("A ring around the mouse pointer that is easy to spot, optionally filled by your global cooldown or cast.", "Хорошо заметное кольцо вокруг указателя мыши, которое может заполняться глобальным восстановлением или заклинанием.")
T("A ring around the mouse pointer that makes it easy to find. Pick its shape, size, color, an optional short trail and a centre dot; No ring keeps only the dot or the progress fill. The camera mode shows ring, dot and trail only while you hold a mouse button down on the game world to turn the camera. The highlight follows the pointer only while something is shown, and it moves nothing while the pointer rests.", "Кольцо вокруг указателя мыши, чтобы его было легко найти. Выберите форму, размер, цвет, короткий след и точку в центре; «Без кольца» оставляет только точку или заливку прогресса. Режим камеры показывает кольцо, точку и след, только пока вы удерживаете кнопку мыши на игровом мире, поворачивая камеру. Подсветка следует за указателем, только пока что-то показано, и ничего не двигает, пока указатель неподвижен.")
T("A small summary sits beside the Character tab of your character sheet and leaves with it. It lists your gear with gem sockets and how many are filled, open ones in amber (click a line to open socketing), the total durability of your gear and, if you like, your PvP item level. Its buttons open the Great Vault and the current expansion page. It updates while the sheet is open, at most once per frame.", "Небольшая сводка находится рядом с вкладкой «Персонаж» и исчезает вместе с ней. Она показывает снаряжение с гнёздами и сколько из них заполнено, пустые — янтарным (щёлкните строку, чтобы вставить камень), общую прочность снаряжения и при желании уровень предметов PvP. Её кнопки открывают Великое хранилище и страницу текущего дополнения. Обновляется, пока окно открыто, не чаще раза за кадр.")
T("A soft light behind the map, independent of the border and artwork.", "Мягкий свет за картой, независимый от рамки и декора.")
T("A summary with gem sockets, durability, PvP item level and Great Vault and expansion buttons, durability on the model, cropped slot icons and item levels on equipment choices.", "Сводка с гнёздами, прочностью, уровнем предметов PvP и кнопками Великого хранилища и дополнения, прочность на модели, обрезанные значки ячеек и уровни предметов при выборе снаряжения.")
