T("Accept and turn in quests automatically. Hold Shift to pause. Reward choices and quests with a money cost stay manual.", "Автоматически принимать и сдавать задания. Удерживайте Shift, чтобы приостановить. Выбор награды и задания с оплатой остаются ручными.")
