T("Accept only ordinary party invitations from the relationship types you select. Invites remain manual in combat, while grouped, during queue-loss or quest-session confirmations, or when Blizzard asks you to choose a role. The native popup handles the final action.", "Принимайте только обычные приглашения в группу от выбранных категорий знакомых. В бою, если вы уже в группе, при возможной потере очереди или подтверждения сеанса заданий, а также при запросе роли от Blizzard приглашения обрабатываются вручную. Последнее действие выполняет стандартное окно Blizzard.")
T("Accept ordinary party invites from selected friends or guild members when no queue or confirmation would be lost.", "Принимать обычные приглашения в группу от выбранных друзей или членов гильдии, если при этом не будет потеряна очередь или подтверждение.")
