T("Adds automatic collection on top of Blizzard's own Auto Loot setting, which stays unchanged. Locked slots and confirmations stay manual.", "Добавляет автоматический сбор поверх настройки Blizzard «Автоматический сбор добычи», которая не меняется. Заблокированные ячейки и подтверждения остаются ручными.")
T("Adds guild rank, the hovered unit's target, item levels, the unit's current mount and item or spell details to Blizzard's main tooltip, and can show player names without titles. Your own item level and the one of the unit open in the Inspect window need no request. Item levels of other hovered players are a separate choice that sends inspect requests: at most one per hover, never while the Inspect window or another inspect is busy. Mounts are read once when a unit tooltip opens, out of combat; a change appears on the next hover. Place the fixed corner in MSUF Edit Mode; the cursor offsets apply to the cursor anchor.", "Добавляет к основной подсказке Blizzard звание в гильдии, цель юнита, уровни предметов, текущее средство передвижения юнита и сведения о предметах или заклинаниях, а также может показывать имена игроков без званий. Ваш собственный уровень предметов и уровень юнита в окне осмотра не требуют запроса. Уровни предметов других игроков под курсором — отдельная настройка, которая отправляет запросы осмотра: не больше одного за наведение и никогда, пока окно осмотра или другой осмотр заняты. Средства передвижения читаются один раз при открытии подсказки юнита вне боя; изменение появится при следующем наведении. Фиксированный угол задаётся в режиме редактирования MSUF; смещения курсора относятся к привязке к курсору.")
T("Adds the current-season Mythic+ score to the main tooltip of another player when Blizzard provides a public score. Unknown or restricted scores stay hidden.", "Добавляет счет Mythic+ текущего сезона в основную подсказку другого игрока, когда Blizzard предоставляет общедоступный счет. Неизвестные или ограниченные результаты остаются скрытыми.")
T("Adjust the glass effect while keeping your colors and window coverage.", "Настройте эффект стекла, сохранив свои цвета и покрытие окон.")
T("Adventure Guide", "Путеводитель по приключениям")
T("After a completed Mythic+ run or successful raid encounter, show the public result values in a separate card. Choose which figures appear and how long the card stays open. The last result can be reopened here. Combat delays the card until it is safe to show.", "После завершения забега эпохального+ или победы в рейдовом бою показывает открытые результаты на отдельной карточке. Выберите показатели и время её отображения. Последний результат можно открыть здесь повторно. В бою показ откладывается до безопасного момента.")
T("After closing the chest loot", "После закрытия добычи из сундука")
