T("An MSUF-owned objective tracker with grouped, readable entries.", "Собственный список заданий MSUF со сгруппированными, удобочитаемыми записями.")
T("An adjacent button opens a small menu for expansion, Great Vault, Adventure Guide and world map pages. Blizzard's landing button keeps its own click behavior. Menu actions are disabled in combat.", "Соседняя кнопка открывает небольшое меню расширения, страницы Великого Хранилища, Путеводителя по приключениям и карты мира. Кнопка приземления Blizzard сохраняет собственное поведение при нажатии. Действия меню отключены в бою.")
T("An empty allow-list includes every quest. Separate quest IDs with spaces or commas. Daily and weekly exclusions leave a quest manual if its frequency cannot be read. Existing profiles keep their previous behavior until you enable an exclusion.", "Пустой список разрешенных включает все задания. Разделяйте ID заданий пробелами или запятыми. Исключения ежедневных и еженедельных заданий оставляют задание ручным, если его периодичность не удается определить. Существующие профили сохраняют прежнее поведение, пока вы не включите исключение.")
T("Animated color flashes that celebrate a level, an achievement or Bloodlust, at random times if you like, and can spin the Suite action bars once.", "Анимированные цветные вспышки в честь уровня, достижения или Жажды крови, по желанию и в случайные моменты; могут один раз прокрутить панели команд Suite.")
