T("Blizzard owns aggro flashes, progressive highlights and soft target icons. Optional colors tint Blizzard's existing threat textures; its health bar threat color stays under the role-color overlay. Soft target icons also need the nameplate icon switch enabled and a matching soft target in game.", "Blizzard управляет миганием агро, постепенной подсветкой и значками мягкого выбора цели. Дополнительные цвета окрашивают существующие текстуры угрозы; цвет угрозы полосы здоровья остаётся под слоем цвета роли. Для значков мягкой цели также нужны включённые значки индикаторов и соответствующая мягкая цель в игре.")
T("Blizzard owns the aura icons and updates. Choose Keep Blizzard setting or Customize for each unit type. Buffs, debuffs and control effects can be selected and dragged separately in the preview. Aura size uses Blizzard's own setting.", "Blizzard управляет значками аур и их обновлением. Для каждого типа юнитов выберите «Оставить настройку Blizzard» или «Настроить». Баффы, дебаффы и эффекты контроля можно выбирать и перетаскивать в предпросмотре по отдельности. Размер аур задается собственной настройкой Blizzard.")
T("Blizzard owns these elements. The rarity icon setting applies to all nameplates; raid target icons are hidden only on enemy plates. Castbar details control Blizzard's own castbar. The preview and live plates use the same switches.", "Blizzard управляет этими элементами. Настройка значка редкости действует на все индикаторы здоровья; значки рейдовых меток скрываются только на индикаторах врагов. Детали полосы произнесения управляют собственной полосой Blizzard. Предпросмотр и живые индикаторы используют одни и те же переключатели.")
T("Blizzard personal auras", "Личные ауры Blizzard")
T("Blizzard plate size (health bar + elements)", "Размер индикатора Blizzard (здоровье + элементы)")
T("Blizzard plate style", "Стиль индикаторов Blizzard")
T("Blizzard raid target icon on enemy plates", "Рейдовая метка Blizzard на индикаторах врагов")
T("Blizzard setting", "Настройка Blizzard")
T("Blizzard shield", "Щит Blizzard")
T("Blizzard spell icon", "Значок заклинания Blizzard")
T("Blizzard supplies the castbar texture, colors, progress and interrupts. Customize its text and details here. Select and move each cast element in the preview; positions apply outside combat.", "Blizzard задает текстуру, цвета, прогресс и прерывания полосы произнесения. Здесь настраиваются ее текст и детали. Выбирайте и перемещайте каждый элемент заклинания в предпросмотре; позиции применяются вне боя.")
T("Blizzard supplies the name and health values. Mapko requests full enemy plates and both health values so normal enemies show text too. Width and height change only the enemy health bar in pixels; 0 keeps the selected bar dimensions. Backdrop, border and role fill are separate live skin layers in the preview; right-click a layer for its setting. Role colors use the saved palette; mana is only a caster hint. Open the three-dot menu here or Nameplates in MSUF Colors to change the palette.", "Blizzard предоставляет имя и значения здоровья. Mapko запрашивает полные индикаторы врагов и оба значения здоровья, чтобы текст отображался и у обычных врагов. Ширина и высота меняют только полосу здоровья врага в пикселях; 0 сохраняет выбранные размеры. Фон, рамка и заливка роли — отдельные слои оформления в предпросмотре; щёлкните слой правой кнопкой, чтобы открыть его настройку. Цвета ролей используют сохранённую палитру; мана лишь указывает на возможного заклинателя. Палитра меняется через меню с тремя точками здесь или через «Индикаторы» в цветах MSUF.")
T("Blizzard symbols", "Значки Blizzard")
T("Blizzard window controls", "Элементы окон Blizzard")
T("Blizzard windows", "Окна Blizzard")
T("Blizzard's Cooldown Manager stops completely. While your MSUF frames follow its bars, MSUF keeps it running invisibly.", "Менеджер восстановления Blizzard полностью останавливается. Пока ваши фреймы MSUF следуют его панелям, MSUF скрыто поддерживает его работу.")
