T("Blizzard's own buttons stay functional. The row is their starting position; drag each icon freely in the preview.", "Собственные кнопки Blizzard продолжают работать. Ряд — их начальное положение; каждый значок можно свободно перетащить в предпросмотре.")
T("Blizzard's own cooldown swipe fills the ring: the global cooldown after each ability, and casts or channels while they run. A cast takes the place of the global cooldown until it ends; the bright edge marks how far the cast has come.", "Анимация восстановления Blizzard заполняет кольцо: глобальное восстановление после каждой способности, а также заклинания и поддерживаемые заклинания, пока они идут. Заклинание заменяет глобальное восстановление до своего окончания; яркий край показывает, насколько оно продвинулось.")
