T("Bubbles outside instances can take the MSUF look; Blizzard locks the ones inside instances. Each source keeps Blizzard's look or uses the MSUF one: the shared look or its own font, size, colors, spacing and width. A bubble is matched to the line it shows right after that line arrives. Turning bubbles off inside instances uses Blizzard's bubble settings and gives them back when you leave or turn it off.", "Облачка речи вне подземелий могут получить стиль MSUF; облачка внутри подземелий Blizzard блокирует. Каждый источник сохраняет вид Blizzard или использует вид MSUF: общий вид или свои шрифт, размер, цвета, отступы и ширину. Облачко сопоставляется со строкой, которую оно показывает, сразу после прихода этой строки. Отключение облачков в подземельях использует настройки облачков Blizzard и возвращает их, когда вы выходите или выключаете параметр.")
