T("Choose %s for \"%s\".", "Выберите %s для «%s».")
T("Choose Clean Modern, Midnight Blue, Midnight Dark, MSUF Forever or Class Style. This changes only the bag window colors and opacity; item slots and Blizzard bag actions remain intact.", "Выберите «Лаконичный модерн», Midnight Blue, Midnight Dark, MSUF Forever или «Стиль класса». Меняются только цвета и прозрачность окна сумок; ячейки предметов и действия Blizzard сохраняются.")
T("Choose Clean Modern, Midnight Blue, neutral Midnight Dark glass or MSUF Forever's dark gold frame. All use MSUF's bar texture and font. Turn the 20 XP divisions on or off. The lower line can show session gain, XP per hour and time to level. Move or resize the bar in MSUF Edit Mode; its popup edits X, Y, width, height and scale. Hover for exact values. A session survives /reload and starts fresh on the next login.", "Выберите Clean Modern, Midnight Blue, нейтральный стеклянный Midnight Dark или темно-золотую рамку MSUF Forever. Все варианты используют текстуру полосы и шрифт MSUF. Можно включить или выключить 20 делений опыта. Нижняя строка показывает опыт за сеанс, опыт в час и время до нового уровня. Перемещайте и меняйте размер полосы в режиме редактирования MSUF; в его окне доступны X, Y, ширина, высота и масштаб. Наведите курсор для точных значений. Сеанс сохраняется после /reload и начинается заново при следующем входе.")
T("Choose Clean Modern, classic MSUF or the complete Forever factory.", "Выберите «Лаконичный модерн», классический MSUF или полный заводской профиль Forever.")
T("Choose Custom layout to set the order of total, per-second and percent values, then pick spaces, brackets or a separator. The percent switch controls main rows; breakdown rows show available shares. Unavailable shares are omitted. Primary means per second for DPS/HPS and total for other meters. Text settings also apply to headers, details and the floating timer. Slug uses WoW's crisp font renderer with an outline and no shadow. Protected values show without a percentage until combat ends.", "Выберите «Пользовательская раскладка», чтобы задать порядок общего значения, значения в секунду и процента, затем выберите пробелы, скобки или разделитель. Переключатель процентов управляет основными строками; строки разбивки показывают доступные доли. Недоступные доли не выводятся. «Основное» означает значение в секунду для DPS/HPS и общее значение для остальных счетчиков. Настройки текста действуют также на заголовки, детали и плавающий таймер. Slug использует четкий рендерер шрифтов WoW с контуром и без тени. Защищенные значения показываются без процента до конца боя.")
T("Choose Suite modules", "Выберите модули Suite")
T("Choose a bar to adjust its layout below. The preview uses sample buttons; empty slots and stances can differ in game.", "Выберите панель, чтобы настроить ее макет ниже. Предпросмотр использует образцы кнопок; пустые ячейки и стойки в игре могут отличаться.")
T("Choose a line, then press Ctrl+C", "Выберите строку и нажмите Ctrl+C")
T("Choose a look", "Выберите стиль")
T("Choose a look and when the Suite bar appears. Visibility rules use the Suite layout; Blizzard layout keeps Blizzard's visibility. MSUF Edit Mode reveals the bar for moving.", "Выберите стиль и условия появления панели Suite. Правила видимости используют макет Suite; макет Blizzard сохраняет видимость Blizzard. Режим редактирования MSUF показывает панель для перемещения.")
T("Choose a look below; this sample follows your changes.", "Выберите стиль ниже; этот образец отражает ваши изменения.")
T("Choose a look, then adjust its colors.", "Выберите стиль и настройте его цвета.")
T("Choose a preset below or fine-tune with the slider.", "Выберите пресет ниже или точно настройте ползунком.")
T("Choose a profile that exists in both parts of the suite", "Выберите профиль, существующий в обеих частях Suite")
T("Choose a random owned Hearthstone variant for the next click", "Выбирать случайный имеющийся вариант камня возвращения для следующего щелчка")
T("Choose a smaller stack size and make sure the item is unlocked, your cursor is empty and you are out of combat.", "Выберите меньший размер стопки. Предмет должен быть разблокирован, курсор пуст, а персонаж вне боя.")
T("Choose a sound", "Выберите звук")
T("Choose a style above or change these colors to make a Custom look. Rows update immediately.", "Выберите стиль выше или измените эти цвета, чтобы создать индивидуальный вид. Строки обновляются немедленно.")
T("Choose a template", "Выберите шаблон")
T("Choose an MSUF font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Label, value and warning colors are separate.", "Выберите шрифт MSUF, контур, тень и рендеринг: «Гладкий», «Четкий» или Slug. У Slug нет тени. Цвета подписи, значения и предупреждения задаются отдельно.")
T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "Выберите шрифт MSUF или SharedMedia и текстуру полосы. Размер шрифта, контур, тень, рендеринг «Гладкий»/«Четкий»/Slug, высота полос и интервал сразу обновляют HUD. У Slug нет тени.")
T("Choose broker names and discovered currency IDs per place. Select your current-season crest currencies from the native currency list; saved currency selections work after login without visiting an upgrade NPC. Selection order and separator control the crest block. Observed upgrade stages remain available as an alternative after selecting an upgrade item this login. Hearthstone actions require a deliberate click.", "Выберите имена брокеров и ID обнаруженных валют для каждой позиции. Выберите валюты гербов текущего сезона из стандартного списка; сохранённый выбор работает после входа без посещения персонажа улучшения предметов. Порядок выбора и разделитель управляют блоком гербов. Обнаруженные ступени улучшения остаются альтернативой после выбора улучшаемого предмета в текущем сеансе. Действия с камнем возвращения требуют намеренного щелчка.")
T("Choose buffs and consumables to track.", "Выберите отслеживаемые положительные эффекты и расходуемые предметы.")
T("Choose crest currencies", "Выбрать валюты гербов")
T("Choose currencies", "Выбрать валюты")
T("Choose data for place %d", "Данные для места %d")
T("Choose each Blizzard popup separately. The feature hides its window when it appears and leaves the underlying game events intact. Combat lockdown can prevent hiding a protected window.", "Выберите каждое всплывающее окно Blizzard отдельно. Эта функция скрывает свое окно при его появлении и оставляет основные игровые события нетронутыми. Боевая блокировка может помешать скрыть защищенное окно.")
T("Choose individual recurring UI errors to hide with Blizzard's own message filter.", "Выбирайте отдельные повторяющиеся ошибки пользовательского интерфейса, чтобы скрыть их с помощью собственного фильтра сообщений Blizzard.")
T("Choose observed seasonal stages", "Выбрать обнаруженные сезонные ступени")
T("Choose the detailed character view and its extra information. Changing the view reloads the UI.", "Выберите подробный вид персонажа и дополнительные сведения. Смена вида перезагружает интерфейс.")
T("Choose the dungeon difficulties where MSUF starts the combat log. Mythic+ begins when the keystone starts.", "Выберите сложности подземелий, в которых MSUF начинает запись журнала боя. В эпохальном+ запись начинается с активацией ключа.")
T("Choose the information shown in each bar.", "Выберите информацию для каждой панели.")
T("Choose the map shape, then adjust its border and outer shadow.", "Выберите форму карты, затем настройте ее рамку и внешнюю тень.")
T("Choose the raid difficulties where MSUF starts the combat log.", "Выберите сложности рейдов, в которых MSUF начинает запись журнала боя.")
T("Choose the shared button colors and frame. Layout, bindings and visibility stay as set. Changing an individual color switches the label to Custom.", "Выберите общие цвета кнопок и рамку. Макет, назначения клавиш и видимость остаются прежними. Изменение отдельного цвета переключает подпись на «Пользовательский».")
T("Choose the values shown on each bar.", "Выберите значения, отображаемые на каждой полосе.")
T("Choose what the Suite tracker lists and when it steps aside.", "Выберите, что показывает список заданий Suite и когда он уступает место.")
T("Choose where recent actions appear. Delves have their own switch; battlegrounds and arenas share one, and other scenarios follow Outside instances. Where the tracker is switched off, it does not listen to your casts.", "Выберите, где показывать последние действия. У вылазок свой переключатель; поля боя и арены делят один, а остальные сценарии следуют пункту «Вне подземелий». Там, где отслеживание выключено, оно не следит за вашими заклинаниями.")
T("Choose which Blizzard interfaces receive the skin. Blizzard keeps their interactions.", "Выберите интерфейсы Blizzard, к которым применяется скин. Взаимодействие с ними остается за Blizzard.")
T("Choose your bars", "Выберите панели")
T("Choose your profile", "Выберите профиль")
T("Choosing a look updates Skinning and every enabled Suite module. Modules enabled later inherit it. New skin profiles start with %s.", "Выбор стиля обновляет скины и все включенные модули Suite. Модули, включенные позже, наследуют его. Новые профили скина начинаются со стиля %s.")
T("Cinematic confirmation can be skipped after you choose to exit. Automatic skipping is a separate option and also skips movies. Both stay inactive during combat, and a vehicle sequence always keeps its exit confirmation. Hide tutorials while this helper is enabled, prefill the DELETE word while keeping the final confirmation manual, hide only the successful screenshot notice, or open your character window at merchants on the tab you used last. At the auction house, Blizzard's filter button is marked while Current Expansion Only is off; tick it there once and Blizzard keeps it for this character.", "Подтверждение можно пропустить после вашего решения выйти из сцены. Автоматический пропуск — отдельная настройка, действующая и на видеоролики. Обе функции не работают в бою, а сцена в транспорте всегда сохраняет подтверждение выхода. Помощник может скрыть обучение, заполнить слово удаления, оставив окончательное подтверждение вам, скрыть только сообщение об успешном снимке экрана или открыть окно персонажа у торговца на последней использованной вкладке. На аукционе кнопка фильтров Blizzard отмечается, пока «Только текущее дополнение» выключено; включите его там один раз, и Blizzard запомнит это для персонажа.")
T("Cinematic zone and event announcements in the Suite look.", "Кинематографичные объявления о зонах и событиях в стиле Suite.")
T("Circle", "Круг")
T("Circle opacity (percent)", "Непрозрачность круга (процент)")
T("Circle size", "Размер круга")
T("Class", "Класс")
T("Class Style", "Стиль класса")
T("Class and group reminders", "Напоминания класса и группы")
T("Class color for player names", "Цвет класса для имен игроков")
T("Class colors for group names in message text", "Цвета классов для имён группы в сообщениях")
T("Class-colored bars", "Полосы цвета класса")
T("Class-colored border", "Рамка цвета класса")
T("Class-colored highlights", "Подсветка цвета класса")
T("Class-colored names", "Имена цвета класса")
T("Class-colored player names", "Имена игроков в цветах классов")
T("Class-colored player names (Retail)", "Имена игроков в цветах классов (Retail)")
T("Class-colored player names are available only in Retail", "Имена игроков цвета класса доступны только в Retail.")
T("Class-colored values", "Значения цвета класса")
T("Classic MSUF  ·  Midnight Blue", "Классический MSUF · Midnight Blue")
T("Classic MSUF factory profile unavailable", "Заводской профиль классического MSUF недоступен")
T("Classic MSUF · complete MSUF, Suite and Skin factory", "Классический MSUF · полный заводской профиль MSUF, Suite и Skin")
T("Classic UI", "Классический интерфейс")
T("Clean Modern", "Лаконичный модерн")
T("Clean Modern  ·  Suite default", "Лаконичный модерн · стандарт Suite")
T("Clean Modern is the Retail default; MSUF Forever is the Forever default. Midnight Blue keeps the original blue glass. Open a section's three-dot menu to change its colors, or use MSUF Colors for the full palette. Your own color changes become Custom.", "«Лаконичный модерн» — стандарт Retail, MSUF Forever — стандарт Forever. Midnight Blue сохраняет исходное синее стекло. Откройте меню раздела с тремя точками для смены его цветов или цвета MSUF для всей палитры. Собственные изменения цвета переводят стиль в пользовательский.")
T("Clean Modern uses matte panels with white accents. Midnight Blue keeps the original blue palette. Midnight Dark uses neutral charcoal glass; MSUF Forever retains its muted gold. Color changes become Custom.", "«Лаконичный модерн» использует матовые панели с белыми акцентами. Midnight Blue сохраняет исходную синюю палитру. Midnight Dark использует нейтральное угольное стекло; MSUF Forever сохраняет приглушённое золото. Изменения цветов переводят стиль в пользовательский.")
T("Clean Modern · Suite and Skin, MSUF frames retained", "Лаконичный модерн · Suite и Skin, рамки MSUF сохранены")
T("Clear", "Очистить")
T("Clear new mount markers", "Очистите новые маркеры крепления.")
T("Clear new mount, pet and toy fanfares acquired while this helper is active.", "Убирает отметки «Новое» у скакунов, питомцев и игрушек, полученных после включения этой функции.")
T("Clear new pet markers", "Убрать отметки «Новое» у питомцев")
T("Clear new toy markers", "Очистите новые игрушечные маркеры")
T("Clear only new mount, pet and toy fanfares acquired while this helper is active. Your collection entries remain available. Each collection type can be switched off independently.", "Убирает только отметки «Новое» у скакунов, питомцев и игрушек, полученных после включения функции. Предметы остаются в коллекции. Каждый тип коллекции можно отключить отдельно.")
T("Clear previous mark", "Убрать предыдущую метку")
T("Clear recent items", "Очистить недавние предметы")
