T("Click for bag options", "Нажмите для настроек сумок")
T("Click opens the world map", "Клик открывает карту мира")
T("Click the minimap button for Blizzard's specialization and loot specialization choices. Choices are disabled in combat and the button hides when both menus are turned off.", "Нажмите кнопку на мини-карте, чтобы просмотреть специализацию Blizzard и выбор специализации для добычи. Выбор отключен в бою, а кнопка скрывается, когда отключены оба меню.")
T("Click to edit this bar, right-click for its actions. Drop a spell here to move it to this bar.", "Нажмите, чтобы изменить эту панель; правый клик — ее действия. Перетащите сюда заклинание, чтобы переместить его на эту панель.")
