T("Color flashes with a banner that names the moment: the level you reached, the achievement you earned, or the Bloodlust-type haste spell that you or your pet cast or that reaches you from anyone in your group (read from your own buffs, which the game may keep hidden during restricted fights). Surprise celebrations can come at random times, around the interval you choose. Spinning turns the Suite action bars once around their centre, only outside combat; entering combat stops the turn at once. Achievements your account had already earned stay quiet. MSUF Edit Mode shows the banner for placing it.", "Цветные вспышки с баннером, который называет момент: достигнутый уровень, полученное достижение или заклинание скорости вроде Жажды крови, примененное вами или вашим питомцем либо полученное от любого участника группы (читается из ваших собственных эффектов, которые игра может скрывать в боях с ограничениями). Праздники-сюрпризы могут появляться в случайное время, около выбранного интервала. Вращение один раз поворачивает панели команд Suite вокруг их центра, только вне боя; начало боя сразу его останавливает. Достижения, которые уже были у учетной записи, не отмечаются. Режим редактирования MSUF показывает баннер для размещения.")
