T("Copies buttons, rows, size, spacing, growth direction and empty slots. Position is never copied.", "Копирует кнопки, ряды, размер, интервал, направление роста и пустые ячейки. Положение никогда не копируется.")
T("Copies keybind and macro name visibility and every text size.", "Копирует видимость назначений клавиш и названий макросов и все размеры текста.")
T("Copies the active Blizzard spell selection, bar assignment and order into this specialization's five built-in Suite bars. Your defensive and custom bars, other specializations, and Blizzard settings stay as they are. You can undo it.", "Копирует активный выбор заклинаний Blizzard, распределение по панелям и порядок в пять встроенных панелей Suite этой специализации. Ваши защитные и свои панели, другие специализации и настройки Blizzard остаются как есть. Это можно отменить.")
T("Copies the bar background with its color, opacity and padding.", "Копирует фон панели с его цветом, непрозрачностью и отступом.")
T("Copies the spells and items you added to this bar to the same bar in your other specializations. Blizzard's entries follow each specialization's own list. You can undo it.", "Копирует заклинания и предметы, добавленные вами на эту панель, на ту же панель в других специализациях. Записи Blizzard следуют собственному списку каждой специализации. Это можно отменить.")
T("Copies when the bar is shown, its opacity, fade and click-through.", "Копирует условия показа панели, ее непрозрачность, затухание и сквозные клики.")
