T("Critical strike, haste, mastery and versatility as your character sheet shows them; leech, avoidance and speed can each join the strip (speed is the stat, not your running speed). Show only in combat hides the strip outside fights. Values the game hides show a dash, and the strip updates from your stat events. MSUF Edit Mode moves the strip.", "Критический удар, скорость, искусность и универсальность так, как их показывает окно персонажа; самоисцеление, избегание и скорость передвижения можно добавить по отдельности (скорость — это характеристика, а не скорость бега). «Показывать только в бою» скрывает полосу вне боя. Значения, которые игра скрывает, показываются прочерком, а полоса обновляется по событиям характеристик. Режим редактирования MSUF перемещает полосу.")
