T("Double-click a search result to open Blizzard's application dialog. With submit on double-click, the second click also signs up with the roles already chosen in that dialog; hold Shift to review it instead. A saved note can appear beside the dialog for copying; it is stored when you finish editing.", "Дважды щелкните результат поиска, чтобы открыть окно заявки Blizzard. С отправкой по двойному щелчку второй щелчок сразу подает заявку с уже выбранными в этом окне ролями; удерживайте Shift, чтобы вместо этого проверить окно. Сохраненная заметка может показываться рядом с окном для копирования; она сохраняется, когда вы заканчиваете правку.")
T("Double-click a search result to open Blizzard's normal application dialog.", "Дважды щелкните результат поиска, чтобы открыть стандартное окно подачи заявки Blizzard.")
T("Drag a window by its top edge; drag the bottom-right corner to scale it. The top-right minus button collapses compatible windows to a restore tab. Bags and protected windows keep their native behavior.", "Перетаскивайте окно за верхний край; перетащите нижний правый угол, чтобы изменить масштаб. Кнопка «минус» в правом верхнем углу сворачивает совместимые окна во вкладку восстановления. Сумки и защищенные окна сохраняют стандартное поведение.")
T("Drag announcements in MSUF Edit Mode, or set their timing, scale and exact position here.", "Перетаскивайте объявления в режиме редактирования MSUF или задайте здесь их время, масштаб и точное положение.")
T("Drag or use arrows to move; Shift: 5, Ctrl: 10.", "Перетаскивайте или двигайте стрелками; Shift: 5, Ctrl: 10.")
T("Drag or use arrows to move; click for settings.", "Перетаскивайте или двигайте стрелками; клик — настройки.")
T("Drag the bag title to move it; click for options.", "Перетащите заголовок сумки для перемещения; нажмите для настроек.")
T("Drag the bar's edge to move it on screen.", "Перетащите край панели, чтобы переместить ее на экране.")
T("Drag the reagent bag title while it is open to move it independently. Click the title for bag options. Reset its position in MSUF Edit Mode to follow Blizzard's normal bag layout again.", "Пока сумка для реагентов открыта, перетащите ее заголовок, чтобы переместить ее отдельно. Нажмите заголовок для настроек сумок. Сбросьте ее положение в режиме редактирования MSUF, чтобы снова следовать стандартной раскладке сумок Blizzard.")
T("Drag the result card in MSUF Edit Mode, or set its screen anchor, width, scale and position here.", "Перетащите карточку результатов в режиме редактирования MSUF или задайте здесь точку привязки, ширину, масштаб и положение.")
T("Drag the title of an open bag to move it. Click the title for bag options. Each bag keeps its own position. Blizzard shows your current gold on the right; the optional Session value on the left shows the change since login and survives /reload. Adjust the combined bag size here or in its MSUF Edit Mode popup. Reset position in Edit Mode returns the window to Blizzard's normal anchor.", "Перетащите заголовок открытой сумки, чтобы переместить ее. Нажмите заголовок для настроек сумок. Каждая сумка хранит свое положение. Blizzard показывает текущее золото справа; дополнительное значение «Сессия» слева показывает изменение с момента входа и сохраняется после /reload. Настройте размер общего окна сумок здесь или в его окне режима редактирования MSUF. Сброс положения в режиме редактирования возвращает окно к стандартной привязке Blizzard.")
