T("Draw the recharge edge independently of the main cooldown edge.", "Показывает границу восстановления заряда независимо от границы основного восстановления.")
T("Draw the recharge swipe independently of the main cooldown swipe.", "Показывает круговую индикацию восстановления заряда независимо от основной.")
