T("Drop an item here to add it without moving it.", "Перетащите сюда предмет, чтобы добавить его без перемещения.")
T("Drop an item onto Pinned items in the category sidebar to keep it at the top of every view. Recent items lists up to 200 item types this character received, also across logins; each leaves the list once it is older than the hours set here, and Clear recent items empties it sooner. Neither action moves or deletes an item.", "Перетащите предмет в «Закреплённые предметы» боковой панели, чтобы он был вверху во всех видах. «Недавние предметы» показывает до 200 типов предметов, полученных этим персонажем, в том числе между входами в игру; каждый пропадает из списка, когда становится старше заданного здесь числа часов, а «Очистить недавние предметы» очищает его раньше. Эти действия не перемещают и не удаляют предметы.")
T("Drops this bar's own order and the spells and items you added to it, for this specialization. Spells you removed stay hidden: Show removed spells brings them back. You can undo it.", "Сбрасывает собственный порядок этой панели, а также добавленные вами заклинания и предметы для этой специализации. Удаленные заклинания остаются скрытыми: «Показать удаленные заклинания» возвращает их. Это можно отменить.")
