T("Enter a spell name or ID on MSUF action bars. Its buttons glow from this buff on you. A page change in combat pauses the glow until combat ends.", "Введите название или ID заклинания на панелях MSUF. Его кнопки светятся по этому эффекту на вас. Смена страницы в бою приостанавливает свечение до конца боя.")
T("Enter a talent or spell name or ID, then press Enter. Every required spell must be learned. Empty removes this condition.", "Введите название или ID таланта либо заклинания и нажмите Enter. Все обязательные заклинания должны быть изучены. Пустое поле удаляет условие.")
T("Enter a talent or spell name or ID, then press Enter. The entry is hidden while any excluded spell is learned. Conditions update outside combat.", "Введите название или ID таланта либо заклинания и нажмите Enter. Запись скрывается, если изучено любое исключённое заклинание. Условия обновляются вне боя.")
T("Enter a texture file ID.", "Введите ID файла текстуры.")
T("Enter a valid spell name or ID", "Введите действительное имя или идентификатор заклинания.")
T("Enter a valid talent or spell name or ID.", "Введите корректное название или ID таланта либо заклинания.")
T("Enter up to 200 item IDs. A button appears only at a merchant and previews eligible stacks; clicking it opens a confirmation. The helper checks item identity, quality, value, quest status and bag position again before requesting sales. Equippable items require a separate opt-in.", "Введите до 200 идентификаторов товаров. Кнопка отображается только у продавца и позволяет просмотреть подходящие стопки; щелчок по нему открывает подтверждение. Помощник еще раз проверяет идентичность предмета, его качество, стоимость, статус задания и положение сумки, прежде чем запрашивать продажу. Экипируемые предметы требуют отдельного согласия.")
T("Enter up to eight spell IDs for movement abilities. When movement begins, the first known, ready and usable spell appears briefly; a shared 20-second cooldown limits notices. Empty IDs do no work. MSUF Edit Mode moves the cue.", "Введите до восьми идентификаторов заклинаний для способностей передвижения. Когда начинается движение, на короткое время появляется первое известное, готовое и пригодное к использованию заклинание; Уведомления об ограничениях общего 20-секундного времени восстановления. Пустые идентификаторы не работают. Режим редактирования MSUF перемещает вызов.")
T("Equal", "Поровну")
T("Equipment", "Экипировка")
T("Equipment category", "Категория экипировки")
T("Equipment choices", "Выбор снаряжения")
T("Equipment choices (the list that opens from a gear slot) show the item level on each item, so you can compare without hovering. The arrows beside the gear slots can be hidden; hold Alt over a slot to open its choices.", "Выбор снаряжения (список, открывающийся из ячейки) показывает уровень каждого предмета, чтобы сравнивать без наведения. Стрелки рядом с ячейками можно скрыть; удерживайте Alt над ячейкой, чтобы открыть выбор.")
T("Equipment item levels appear in the upper right of each slot. Choose a font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Missing item data appears when the client provides it.", "Уровни предметов снаряжения отображаются в правом верхнем углу каждой ячейки. Выберите шрифт, контур, тень и рендеринг: «Гладкий», «Четкий» или Slug. У Slug нет тени. Недостающие данные предметов появляются, когда клиент их предоставляет.")
T("Equipment set name text size", "Размер названия комплекта экипировки")
T("Equipment slot %d", "Ячейка снаряжения %d")
T("Equipment window at upgrades", "Окно экипировки при улучшении")
T("Equipment window at upgrades (Retail)", "Окно экипировки при улучшении (Retail)")
T("Erase this character's Mythic+ history? The removed runs cannot be restored.", "Стереть историю эпохальных+ этого персонажа? Удалённые забеги нельзя восстановить.")
T("Essential bar x/y are an offset from Blizzard's bar", "X/Y основной панели — смещение от панели Blizzard")
T("Essential cooldowns", "Основные восстановления")
T("Estimated time", "Ожидаемое время")
T("Event headline colors", "Цвета заголовков событий")
T("Every specialization already has it.", "Это уже есть во всех специализациях.")
T("Every spell of this bar, unlearned ones included. On a buff bar, Add spells offers received buffs such as Power Infusion and Innervate; Buff on me also accepts a buff aura ID or resolvable name and tracks that ID from any caster. With Show missing buffs off, only active buffs appear. The preview edits entries too: click for options, drag to reorder or onto a bar above, middle-click to remove (with undo). Removed spells stay under Add spells. Lists are kept per specialization.", "Все заклинания этой панели, включая неизученные. На панели баффов «Добавить заклинания» предлагает полученные баффы, например «Придание сил» и «Озарение»; «Бафф на мне» также принимает ID ауры баффа или распознаваемое название и отслеживает этот ID от любого заклинателя. Если «Показывать недостающие баффы» отключено, видны только активные баффы. Предпросмотр тоже редактирует записи: клик — параметры, перетаскивание — порядок или перенос на панель выше, средний клик — удаление (с отменой). Удаленные заклинания остаются в «Добавить заклинания». Списки хранятся для каждой специализации.")
