T("For Warlocks: show Burning Rush only while its aura is active in combat. Blizzard's native aura container follows the aura; Suite does not scan auras. MSUF Edit Mode shows a sample and moves the cue.", "Для чернокнижников: показывать Burning Rush только во время действия его ауры в бою. Стандартный контейнер аур Blizzard отслеживает ауру; Suite не сканирует ауры. Режим редактирования MSUF показывает пример и позволяет переместить уведомление.")
