T("Forever only. Route times are learned from completed flight-master journeys and kept in this profile. A first journey has no invented estimate. Early landing does not overwrite a full-route time. Intermediate stops come from the native taxi map; its tooltip can preview the route. Land at next stop requests the next available landing point.", "Только Forever. Время завершённых перелётов запоминается в этом профиле. Для первого перелёта нет выдуманной оценки. Ранняя посадка не заменяет время полного маршрута. Остановки берутся из стандартной карты полётов, маршрут можно увидеть в подсказке. «Приземлиться на следующей остановке» запрашивает ближайший доступный пункт.")
