T("Friendly player display chooses Blizzard's setting, names for all friendly players, names for party / raid only, or health bars. Names only hides Blizzard bars, casts and auras for friendly players; it does not change NPC or enemy plates. Group / outsider in the preview only changes the sample. Blizzard can forbid changes to friendly plates in instances; those frames stay under Blizzard's control.", "«Показ дружественных игроков» выбирает настройку Blizzard, имена всех дружественных игроков, имена только для группы/рейда или полосы здоровья. Режим «Только имена» скрывает полосы, заклинания и ауры Blizzard у дружественных игроков; индикаторы NPC и врагов не меняются. «Группа / вне группы» в предпросмотре меняет только образец. В подземельях Blizzard может запрещать изменения индикаторов союзников; такие фреймы остаются под контролем Blizzard.")
