T("Hide Blizzard's main tooltip in combat, in instances, or for selected item, spell and unit tooltips. MSUF unit and group frame tooltips keep their own visibility settings; aura tooltips keep their Show Tooltip switches. Each choice works independently. A hidden tooltip turns fully transparent, so Blizzard keeps handling it as usual.", "Скрывает основную подсказку Blizzard в бою, в подземельях или для выбранных предметов, заклинаний и существ. Подсказки рамок юнитов и группы MSUF сохраняют собственные настройки видимости; подсказки аур подчиняются своим переключателям показа подсказок. Каждый выбор работает независимо. Скрытая подсказка становится полностью прозрачной, и Blizzard продолжает обрабатывать её как обычно.")
