T("Hide only the selected error types. Blizzard keeps handling all other messages and their sounds. Each choice remembers and restores its previous display state when you turn it off.", "Скрыть только выбранные типы ошибок. Blizzard продолжает обрабатывать все остальные сообщения и их звуки. Каждый вариант запоминает и восстанавливает предыдущее состояние отображения при его выключении.")
