T("Hide the Suite Micro Bar when any selected condition is true. The health condition uses your character's health; at full health the transparent bar can still receive clicks. MSUF Edit Mode shows the bar for placement. Blizzard layout keeps Blizzard's visibility.", "Скрывать микроменю Suite, когда выполняется любое выбранное условие. Условие здоровья использует здоровье вашего персонажа; при полном здоровье прозрачная панель все равно принимает клики. Режим редактирования MSUF показывает панель для размещения. Макет Blizzard сохраняет видимость Blizzard.")
T("Hide the arrows beside gear slots", "Скрыть стрелки рядом с ячейками")
