T("Hide this bar", "Скрыть эту панель")
T("Hide this bar when any selected condition is true. The health condition uses your character's health. At full health the bar is transparent but can still receive clicks. Edit Mode shows it for placement.", "Скрывать эту панель, когда выполняется любое выбранное условие. Условие здоровья использует здоровье вашего персонажа. При полном здоровье панель прозрачна, но все равно принимает клики. Режим редактирования показывает ее для размещения.")
