T("Hold Alt to see the ID of an item, spell, creature, quest, currency or temporary weapon enchant on its tooltip, or press Alt while the tooltip is open; the IDs stay until the tooltip is built again. Spell icon IDs and Blizzard's account character currency data are optional, and that data joins an open tooltip when it arrives. No ID or quantity appears when the client keeps it private.", "Удерживайте Alt, чтобы увидеть ID предмета, заклинания, существа, задания, валюты или временного чародейства оружия в подсказке, или нажмите Alt при открытой подсказке; ID остаются, пока подсказка не будет построена заново. ID значков заклинаний и данные Blizzard о валюте других персонажей необязательны, и эти данные добавляются в открытую подсказку, когда приходят. ID и количества не показываются, если клиент держит их закрытыми.")
T("Hold Alt to show item, spell, creature, quest, currency and temporary weapon enchant IDs on the main tooltip.", "Удерживайте Alt, чтобы отобразить идентификаторы предметов, заклинаний, существ, квестов, валюты и временных чар для оружия в основной всплывающей подсказке.")
T("Hold Midnight Artisan payouts while Shard of Dundun is capped", "Сохранять выплаты ремесленников Midnight при достижении лимита фрагментов Дандана")
T("Hold Shift to pause. Quests with a money cost and quests with a reward choice always stay manual.", "Удерживайте Shift, чтобы приостановить. Задания с оплатой и задания с выбором награды всегда остаются ручными.")
T("Hold the selected key while clicking Release Spirit. The release button stays hidden until you hold it; resurrection and death recap remain available. Choose where to use the protection. Blizzard's automatic release timer is unchanged.", "Удерживайте выбранную клавишу, нажимая «Освободить дух». Кнопка скрыта, пока клавиша не нажата; воскрешение и сводка смерти остаются доступны. Выберите, где применять защиту. Штатный таймер автоматического освобождения духа не меняется.")
T("Hold to release", "Удерживать для освобождения")
