T("Hover a spell and type /msufcopyspell to select its public ID in a small edit box. Press Ctrl+C to copy it. You can also pass an ID to the command. No clipboard action runs automatically.", "Наведите курсор на заклинание и введите /msufcopyspell, чтобы выбрать его общедоступный идентификатор в небольшом поле редактирования. Нажмите Ctrl+C, чтобы скопировать его. Вы также можете передать команде идентификатор. Никакие действия с буфером обмена не выполняются автоматически.")
