T("How the icons line up and grow. A free bar's position counts from the screen center; an attached bar's is an offset from its attach point. Excess cooldowns can move past Maximum icons to another enabled cooldown bar. The destination must have overflow off; chained routes are ignored.", "Выравнивание и рост значков. Положение свободной панели отсчитывается от центра экрана, прикреплённой — от точки привязки. Лишние восстановления сверх максимума значков можно направить на другую включённую панель. У получателя перенаправление должно быть отключено; цепочки игнорируются.")
