T("Inside a raid the tracker turns into an encounter view at its usual place: boss name, pull timer, the bosses engaged right now with their health, your best wipe and your fastest kill. Phases come from DBM or BigWigs when one is installed; otherwise the phase stays open. A wipe with more bosses down beats one with fewer, and with the same count the one with less boss health left wins. Each character keeps its own records. Boss health shows only while the client reveals it.", "В рейде список заданий на своём обычном месте превращается в вид сражения: имя босса, таймер пула, боссы в бою с их здоровьем, ваш лучший вайп и самое быстрое убийство. Фазы берутся из DBM или BigWigs, если один из них установлен; иначе фаза остаётся неизвестной. Вайп с большим числом побеждённых боссов лучше вайпа с меньшим, а при равном числе выигрывает тот, где у боссов осталось меньше здоровья. Каждый персонаж хранит свои записи. Здоровье боссов видно, только пока клиент его раскрывает.")
