T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "Оставьте сетку Blizzard или выберите единую сетку Suite, группы по отдельным сумкам или категории. Кнопка «Изменить категории» в окне сумок позволяет создавать, переименовывать, упорядочивать и отключать категории; перетаскивайте предметы на категорию в боковой панели для назначения. Для больших инвентарей используйте прокрутку или кнопки «Назад» и «Далее»; в бою все ячейки показываются сразу. Объединение стопок только визуальное; в банке, банке гильдии, почте, обмене, на аукционе и у торговца всегда показываются реальные стопки.")
