T("Learned dungeon portals use secure buttons. Group suggestions require a verified dungeon map or an exact destination match. Unknown destinations show no suggestion; buttons hide in combat.", "Выученные порталы в подземелья используют защищенные кнопки. Подсказка для группы требует подтвержденной карты подземелья или точного совпадения места назначения. Для неизвестных мест подсказки нет; в бою кнопки скрываются.")
