T("Lightweight meter windows for damage, healing, interrupts, dispels, deaths and damage taken. They read the client's own combat data; Blizzard's meter window stays hidden while this module is active.", "Легкие окна счетчика для урона, исцеления, прерываний, рассеиваний, смертей и полученного урона. Они читают собственные боевые данные клиента; окно счетчика Blizzard скрыто, пока этот модуль активен.")
T("Limit the whole highlight to combat, to instances or to the open world, then give the pointer ring, the global cooldown and the cast fill their own combat rule. Nothing follows the pointer while it is hidden.", "Ограничьте всю подсветку боем, подземельями или открытым миром, а затем задайте кольцу указателя, глобальному восстановлению и заливке заклинания собственное правило боя. Пока подсветка скрыта, за указателем ничего не следует.")
