T("Lists carried gem types beside Blizzard's socket window. Inspect each gem with its normal bag tooltip and confirm compatibility in the native socket window before applying it.", "Списки содержали типы драгоценных камней рядом с окном сокета Blizzard. Осмотрите каждый драгоценный камень с помощью его обычной всплывающей подсказки и подтвердите совместимость в окне собственного гнезда, прежде чем применять его.")
T("Lists the casts of attackable enemy nameplates while you are in a five-player dungeon, oldest first; the game runs each bar and timer. The game keeps spell, target, marker and interrupt details hidden from addons, so casts are never sorted or filtered by them: fading or hiding uses the game's important-spell flag (a hidden cast keeps its place in the list), raid markers sit on the spell icon, and the ready mark, an edge stripe or the whole bar, shows on interruptible casts while your interrupt is off cooldown. Dimming checks four times a second whether your interrupt reaches each listed enemy; a cast it cannot check stays bright. The interrupt is found from your talents and pet unless you enter a spell ID. MSUF Edit Mode shows sample casts for placing the list.", "Показывает заклинания атакуемых противников с индикатором здоровья, пока вы в подземелье на пять игроков, начиная с самых ранних; каждую полосу и таймер ведет сама игра. Игра скрывает от аддонов заклинание, цель, метку и возможность прерывания, поэтому список никогда не сортируется и не фильтруется по ним: приглушение или скрытие использует отметку важного заклинания от игры (скрытое заклинание сохраняет свое место в списке), рейдовые метки показываются на значке заклинания, а метка готовности, полоска у края или вся полоса, появляется на прерываемых заклинаниях, пока ваше прерывание не на перезарядке. Затемнение четыре раза в секунду проверяет, достает ли ваше прерывание до каждого противника в списке; заклинание, которое нельзя проверить, остается ярким. Прерывание определяется по талантам и питомцу, если вы не ввели ID заклинания. Режим редактирования MSUF показывает примеры заклинаний для размещения списка.")
T("Lists the casts of enemy nameplates in five-player dungeons, oldest first, with timers the game runs.", "Показывает заклинания вражеских индикаторов здоровья в подземельях на пять игроков, начиная с самых ранних, с таймерами, которые ведет игра.")
