T("MSUF icons replace the scattered Blizzard chat controls. Friends, channels, text to speech and the chat menu keep their Blizzard actions; the bottom icon jumps to the newest message. Turn this off to restore the native buttons.", "Значки MSUF заменяют разбросанные элементы управления чатом Blizzard. Друзья, каналы, озвучивание текста и меню чата сохраняют действия Blizzard; нижний значок переходит к новейшему сообщению. Отключите, чтобы вернуть стандартные кнопки.")
