T("Mainline covers Rogue poisons, this season's flasks, augment runes and weapon oils, and the Well Fed food buff. Each category clicks the first matching item in your bags; an item you enter for it is tried first. Food is found in your bags by the game's eating spells: the food you enter comes first, then the newest one. With the gray reminder on, a category with nothing left stays visible without a click action. Assassination prefers Deadly Poison; Outlaw and Subtlety prefer Instant Poison. Dragon-Tempered Blades allows two poisons per category. Oils target equipped weapons; known Shaman or Paladin imbues suppress automatic oils.", "Mainline охватывает яды разбойника, настои, усиливающие руны и масла для оружия этого сезона, а также эффект пищи «Сытость». Каждая категория по щелчку использует первый подходящий предмет из сумок; предмет, указанный для неё, пробуется первым. Еда находится в сумках по заклинаниям трапезы из игры: сначала указанная, затем самая новая. С серым напоминанием закончившаяся категория остаётся видимой без действия по щелчку. Ликвидация предпочитает Смертоносный яд, Головорез и Скрытность — Быстродействующий яд. Закаленные драконом клинки позволяют два яда на категорию. Масла наносятся на надетое оружие; известные чары шамана или паладина отключают автоматические масла.")
