T("Mapko uses Modern plates, Medium size and the same bar dimensions on Retail and Forever. Guild names and titles also affect names in the world. Bind Toggle friendly NPC nameplates under MSUF Suite in Blizzard Key Bindings. Import protection keeps your current nameplates when importing a full Suite profile; explicit nameplate imports still replace them.", "Mapko использует современные индикаторы среднего размера и одинаковые размеры полос в Retail и Forever. Названия гильдий и титулы также влияют на имена в мире. Назначьте «Переключить индикаторы дружественных NPC» в разделе MSUF Suite настроек клавиш Blizzard. Защита импорта сохраняет текущие индикаторы при импорте полного профиля Suite; отдельный импорт индикаторов по-прежнему заменяет их.")
