T("Observed enemies adds up the enemy forces of the living enemies in combat that you see as a nameplate or target, and the total they would bring. Enemies that give no forces count as zero; while the client keeps a value hidden, the line shows -- instead of a guess. Enemies out of sight are not counted.", "«Наблюдаемые враги» складывает прогресс сил противника от живых врагов в бою, которых вы видите по индикатору имени или как цель, и показывает итог, который они дадут. Враги без вклада считаются нулём; пока клиент скрывает значение, строка показывает -- вместо догадки. Враги вне поля зрения не учитываются.")
