T("Only containers newly acquired after enabling this helper are opened. It waits for combat to end, opens one at a time, and leaves them to you while you hold Shift or a loot window or a window that gives item use another meaning is open: merchant, bank, guild bank, mail, trade, auction house, scrapper, socket, upgrade and similar. Warbound containers stay unopened unless you allow them; profiles that used this helper before keep opening them. Midnight Artisan payouts can wait while your Shard of Dundun is capped.", "Открываются только контейнеры, полученные после включения функции. Она ждет окончания боя, открывает их по одному и оставляет вам, пока зажат Shift или открыто окно добычи либо окно, придающее использованию предмета другой смысл: торговец, банк, банк гильдии, почта, обмен, аукцион, утилизатор, вставка камней, улучшение и подобные. Контейнеры отряда остаются закрытыми, если вы их не разрешите; профили, уже пользовавшиеся функцией, продолжают их открывать. Выплаты ремесленников Midnight могут подождать, пока ваши фрагменты Дандана на пределе.")
T("Only in an active Delve and outside combat: if the player choice has exactly one enabled spell option, one button and no confirmation, MSUF selects it once. Other choices remain manual.", "Только в активном Спуске и вне боя: если выбор игрока включает ровно один вариант заклинания, одну кнопку и отсутствие подтверждения, MSUF выбирает его один раз. Другие варианты остаются ручными.")
T("Only inside instances", "Только в подземельях")
