T("Open your equipment window beside an item upgrade merchant and close only the window MSUF opened.", "Откройте окно вашего оборудования рядом с торговцем улучшений предметов и закройте только открытое окно MSUF.")
T("Opens your character window, on the tab you used last, when an item upgrade merchant opens. It closes only a window this helper opened and waits for the end of combat to open or close it.", "Открывает окно персонажа на последней использованной вкладке, когда открывается торговец улучшением предметов. Закрывает только окно, открытое этим помощником, а открытие или закрытие в бою откладывает до его окончания.")
T("Optional Blizzard settings for chat, map, sound and low-health or alternate screen flashes. MSUF restores the previous value when you turn a choice or this helper off. Changes you make yourself in Blizzard settings while this helper runs are respected.", "Дополнительные настройки Blizzard для чата, карты, звука и низкого уровня работоспособности или альтернативного мигания экрана. MSUF восстанавливает предыдущее значение, когда вы выключаете выбор или этот помощник. Изменения, которые вы вносите в настройки Blizzard во время работы этого помощника, учитываются.")
T("Optional artwork and spacing controls. Use MSUF Edit Mode for position, nudging, reset, undo and redo.", "Дополнительные элементы декора и интервалов. Используйте режим редактирования MSUF для положения, точного сдвига, сброса, отмены и повтора.")
