T("Pick the places where reminders may show; arenas and battlegrounds never show them. Before a keystone starts, buffs can be asked to last the dungeon's timer or a number of minutes; once the key starts, the normal warning time applies again. One scheduled wakeup handles the next expiry.", "Выберите места, где могут появляться напоминания; на аренах и полях боя их нет никогда. До начала ключа можно потребовать, чтобы эффекты длились весь таймер подземелья или заданное число минут; после запуска ключа снова действует обычное время предупреждения. Одно запланированное пробуждение отвечает за следующее истечение.")
