T("Priority: focus, safe tank aggro, threat, tapped, quest, neutral, then NPC type. Turning focus off allows the next rule. Disabled threat overrides preserve Blizzard's active threat color. Tank mode uses your effective role; warnings also work for damage/healers. Secret values stay with Blizzard.", "Приоритет: фокус, надежное агро танка, угроза, занят другими, задание, нейтральный, затем тип NPC. Отключение фокуса передает ход следующему правилу. Отключенные переопределения угрозы сохраняют активный цвет угрозы Blizzard. Режим танка использует вашу фактическую роль; предупреждения работают и для бойцов/целителей. Секретные значения остаются за Blizzard.")
