T("Reminders appear only outside combat. The advance setting also shows active buffs, food and weapon enchants when their remaining time reaches the chosen number of minutes; 0 shows only missing effects. A single scheduled wakeup handles the next threshold. Reminders hide in arenas and battlegrounds, where aura data can be restricted.", "Напоминания появляются только вне боя. Опережающая настройка также показывает активные баффы, еду и чары оружия, когда их оставшееся время достигает выбранного числа минут; 0 показывает только отсутствующие эффекты. Следующий порог обрабатывается одним запланированным пробуждением. Напоминания скрываются на аренах и полях боя, где данные аур могут быть ограничены.")
T("Reminders for missing poisons and consumables.", "Напоминания об отсутствующих ядах и расходуемых предметах.")
