T("Repair", "Ремонт")
T("Repair equipment and sell poor-quality items when a merchant opens. Hold Shift to skip selling.", "Ремонтирует снаряжение и продает предметы низкого качества при открытии окна торговца. Удерживайте Shift, чтобы пропустить продажу.")
T("Repairs only when the cost is within your limit. Guild funds are used first when allowed.", "Ремонт выполняется, только если стоимость в пределах вашего лимита. Если разрешено, сначала используются средства гильдии.")
T("Replace Blizzard event banners", "Заменить баннеры событий Blizzard")
T("Replace objectives with the Mythic+ timer during a key", "Заменять задачи таймером эпохального+ во время ключа")
T("Replaces the merchant's pages with one list; scroll it with the mouse wheel or the bar. Right-click buys, left-click picks an item up and Shift-click asks for a quantity; linking and previewing work as usual. Purchases paid with currencies or items, or costing at least 150 gold, ask for confirmation first. The buyback tab keeps Blizzard's layout. Drop or click an item from your bags onto the list to sell it; one you can still refund asks whether to refund it.", "Заменяет страницы торговца одним списком; прокручивайте его колесом мыши или полосой. Правый клик покупает, левый клик берёт предмет, Shift-клик спрашивает количество; ссылки и предпросмотр работают как обычно. Покупки за валюту или предметы либо от 150 золотых сначала запрашивают подтверждение. Вкладка выкупа сохраняет оформление Blizzard. Перетащите предмет из сумок на список или щёлкните им по списку, чтобы продать; если его ещё можно вернуть, список спросит, вернуть ли его.")
T("Report junk sale requests in chat", "Сообщать о продаже хлама в чат")
T("Reports group member deaths in chat during combat.", "Сообщает о смерти членов группы в чате во время боя.")
T("Reports the first observed death of each group member during combat. Local chat, a screen notice and a sound can be selected separately. Simultaneous deaths share one sound. Optionally include your own death. The listener is active only while you are grouped and in combat.", "Сообщает о первой замеченной смерти каждого участника группы в бою. Локальный чат, уведомление на экране и звук выбираются отдельно. При одновременных смертях звучит один сигнал. Можно включить собственную смерть. Отслеживание работает только в группе и в бою.")
T("Reputation", "Репутация")
