T("Restores this bar's default spells and buffs for your specialization. Other bars and specializations stay as they are. You can undo it.", "Восстанавливает заклинания и баффы этой панели по умолчанию для вашей специализации. Другие панели и специализации остаются как есть. Это можно отменить.")
T("Results and details", "Результаты и подробности")
T("Resurrection offers", "Предложения воскрешения")
T("Retail Druids only. Every incoming whisper in combat is a possible Innervate cue; message text cannot be inspected reliably during chat lockdown. The alert waits for a publicly known Innervate cooldown, or shows a generic cue when readiness is unavailable. A preferred target can be outlined on an MSUF group frame resolved outside combat. MSUF Edit Mode previews the alert and edits its position and size.", "Только для друидов в Retail. Каждый входящий шепот в бою считается возможным сигналом для «Озарения»; текст сообщения нельзя надежно проверить во время блокировки чата. Оповещение ждет общеизвестного времени восстановления «Озарения» или показывает общий сигнал, когда готовность неизвестна. Предпочитаемую цель можно обвести на групповом фрейме MSUF, определенном вне боя. Режим редактирования MSUF показывает оповещение и позволяет изменить его положение и размер.")
T("Retail only. Shows while Skyriding is available, or only in flight if selected. Choose bars or Blizzard Vigor gems; gem scale and a refill sound are optional. Separate bar heights, Surge icon size and speed-value offsets are under Text and bars. MSUF Edit Mode previews the HUD. Unknown charge values display as dashes.", "Только Retail. Показывается при доступности динамического полёта или только в полёте по выбору. Выберите полосы или камни энергии Blizzard; масштаб и звук восстановления необязательны. Отдельные высоты, размер значка рывка и смещения скорости находятся в разделе «Текст и полосы». Режим редактирования MSUF показывает предпросмотр. Неизвестные заряды обозначаются тире.")
T("Return to the current fight when combat starts", "Возвращаться к текущему бою в начале боя")
T("Returns this specialization to its short raid essentials list. Your other bars and specializations stay as they are. You can undo it.", "Возвращает этой специализации короткий список основных рейдовых способностей. Другие панели и специализации остаются как есть. Это можно отменить.")
