T("Selected currencies appear above the bag footer. Click Gold history for recorded character balances and 30 days of this character's income and spending, by local date. Other characters show their last recorded balance. The history starts when enabled and does not reconstruct earlier transactions; Clear saved character gold removes the history and the balances.", "Выбранные валюты отображаются над нижней панелью сумок. Нажмите «История золота», чтобы увидеть записанные балансы персонажей, а также доходы и расходы этого персонажа за 30 дней по местной дате. Для других персонажей показан последний записанный баланс. История начинается после включения и не восстанавливает прошлые операции; «Очистить сохранённые данные о золоте персонажей» удаляет историю и балансы.")
T("Selected profession outfits and cosmetic auras are removed outside combat. Fishing is excluded. Noggenfogger skeleton removal also removes its underwater-breathing effect. Client refusal stops this helper until settings change.", "Выбранные профессиональные наряды и косметические ауры снимаются вне боя. Рыбная ловля исключена. Снятие облика скелета Гогельмогеля также снимает подводное дыхание. При отказе клиента функция останавливается до изменения настроек.")
