T("Show the enemy forces bar", "Показывать полосу сил противника")
T("Show the enemy forces text", "Показывать текст сил противника")
T("Show the global cooldown in its own circle instead of the ring", "Показывать глобальное восстановление в отдельном круге вместо кольца")
T("Show the global cooldown on icons", "Показывать общее восстановление на значках")
T("Show the global cooldown swipe for this spell. Reset follows the global cooldown setting in Basics.", "Показывает круговую индикацию общего восстановления для этого заклинания. После сброса используется настройка общего восстановления из раздела «Основное».")
T("Show the icon only while the spell is on cooldown.", "Показывать значок, только пока заклинание восстанавливается.")
T("Show the item level on equipment sold by a merchant.", "Показывать уровень предмета на снаряжении, продаваемом торговцем.")
