T("Show the summary beside the character sheet", "Показывать сводку рядом с окном персонажа")
T("Show the swipe edge", "Показывать край затемнения")
T("Show the target time of bosses still alive", "Показывать целевое время живых боссов")
T("Show this bar", "Показывать эту панель")
