T("Show time to level", "Показывать время до уровня")
T("Show tooltips", "Показывать подсказки")
T("Show tracker heading", "Показывать заголовок отслеживания")
T("Show unit level", "Показывать уровень")
T("Show unit titles", "Показывать титулы существ")
T("Show upgrade threshold markers", "Показывать отметки порогов улучшения")
T("Show upgrade track and rank", "Показывать путь улучшения и ранг")
