T("Show versatility", "Показать универсальность")
T("Show weather", "Показывать погоду")
T("Show weather as text, an icon, or both. Choose Blizzard icons or original Forever artwork. The tooltip keeps the weather name when only the icon is shown.", "Показывает погоду текстом, значком или обоими способами. Выберите значки Blizzard или оригинальное оформление Forever. Название погоды остаётся в подсказке, даже когда показан только значок.")
T("Show weekly reward item levels", "Уровни предметов еженедельной награды")
T("Show who each cast targets", "Показывать цель каждого заклинания")
T("Show windows", "Показывать окна")
T("Show your Bloodlust exhaustion or ready state while grouped.", "Покажите свое изнеможение или готовность от Жажды крови, находясь в группе.")
T("Show your owned item count, including bank and Warband bank, on item tooltips.", "Покажите количество принадлежащих вам предметов, включая банк и банк Warband, во всплывающих подсказках к предметам.")
T("Show your selected loot specialization in the Great Vault window.", "Показывать выбранную специализацию для добычи в окне Великого хранилища.")
T("Show zone", "Показывать зону")
T("Shown value", "Показываемое значение")
T("Shown windows: %d. Raise the number of windows to show this one.", "Показано окон: %d. Увеличьте количество окон, чтобы показать это.")
T("Shows Blizzard's shared battle resurrection charges in an active Mythic+ run or raid encounter. The icon counts down to the next charge using Blizzard's cooldown display. Hidden when the shared pool is unavailable. MSUF Edit Mode previews the display and edits X, Y, width, height and scale.", "Показывает общие заряды боевого воскрешения Blizzard в активном эпохальном+ или рейдовой битве. Значок отсчитывает время до следующего заряда с помощью отображения восстановления Blizzard. Скрыт, когда общий запас недоступен. Режим редактирования MSUF показывает образец и позволяет изменить X, Y, ширину, высоту и масштаб.")
T("Shows an approximate range to your current target from the game's range checks of spells you know; values include the target's hitbox, and dashes mean that no known spell can tell. Write the text with {range} and {unit}. The estimate can sit below the target frame, following it when the frame moves, or anywhere on screen; MSUF Edit Mode moves both placements.", "Показывает примерное расстояние до текущей цели по проверкам дальности известных вам заклинаний; значения учитывают размер цели, а прочерки означают, что ни одно известное заклинание не может это определить. Текст задается через {range} и {unit}. Оценку можно разместить под рамкой цели (она следует за рамкой, когда та перемещается) или в любом месте экрана; режим редактирования MSUF перемещает оба варианта.")
T("Shows item levels on merchant equipment when Blizzard has loaded its item data. Buyback items and items without an item level stay unchanged.", "Показывает уровни предметов на снаряжении торговца, когда Blizzard загрузила данные предметов. Предметы для выкупа и предметы без уровня не меняются.")
T("Shows the current loot specialization when you open the Great Vault. Updates if you change loot specialization while the window is open.", "Показывает текущую специализацию для добычи при открытии Великого хранилища. Обновляется, если вы меняете ее, пока окно открыто.")
T("Shows the lowest equipped durability below your chosen threshold, outside combat. MSUF Edit Mode shows a sample even when your gear is repaired. Its popup edits X, Y, width, height and scale.", "Показывает самую низкую прочность надетого снаряжения ниже выбранного порога, вне боя. Режим редактирования MSUF показывает образец, даже если снаряжение отремонтировано. Его окно настраивает X, Y, ширину, высоту и масштаб.")
T("Shows the number you own, including your bank and Warband bank, when the item tooltip has a public item ID. Optionally separate storage locations. Empty counts are omitted.", "Показывает номер, которым вы владеете, включая ваш банк и банк Warband, когда во всплывающей подсказке предмета указан общедоступный идентификатор предмета. Опционально отдельные места хранения. Пустые счетчики опускаются.")
T("Shows the total durability of your gear on the character model, moved by the two offsets, and crops the edges of the gear slot icons on your character sheet and in the Inspect window.", "Показывает общую прочность снаряжения на модели персонажа со сдвигом на два смещения и обрезает края значков ячеек в окне персонажа и окне осмотра.")
T("Shows up to three extra compact notices for Blizzard personal item-loot toasts. Filter by minimum quality, mount or pet items, and optionally up to 100 item IDs. Native Blizzard notices remain visible; ordinary bag additions without a toast are not included.", "Показывает до трех дополнительных компактных уведомлений о личной добыче Blizzard. Фильтр по минимальному качеству, предметам скакунов или питомцев и, при желании, по списку до 100 ID предметов. Стандартные уведомления Blizzard остаются видимыми; обычные предметы, попавшие в сумки без уведомления, не учитываются.")
T("Shows your current talent build and loot specialization on ready checks, when a dungeon queue pops, or when you enter an instance. It never changes your talents or loot spec.", "Показывает текущий набор талантов и специализацию добычи при проверке готовности, появлении очереди в подземелье или входе в него. Таланты и специализация добычи не изменяются.")
T("Shows your most recent successful spells. Standard rows have an icon, name and marker; Icons only is a compact vertical icon column. Display width applies to standard rows; icon width follows row height in the icon preset. Position and anchor are set in MSUF Edit Mode, which shows sample actions. The list stops listening while disabled. Spells whose details the client keeps private cannot appear.", "Показывает последние успешно примененные заклинания. В обычных строках есть значок, название и маркер; режим «Только значки» показывает компактный вертикальный столбец. Заданная ширина действует для обычных строк; в режиме значков их ширина следует за высотой строки. Положение и привязка настраиваются в режиме редактирования MSUF, где видны примеры действий. При отключении список перестает отслеживать заклинания. Заклинания, сведения о которых клиент скрывает, не показываются.")
T("Shows your own Bloodlust exhaustion while in a group, or a ready state if you prefer. Relevant player aura changes update it; MSUF Edit Mode moves it and previews the locked state.", "Показывает вашу собственную усталость от Жажды крови, когда вы находитесь в группе или в состоянии готовности, если хотите. Соответствующие изменения ауры игрока обновляют ее; Режим редактирования MSUF перемещает его и просматривает заблокированное состояние.")
