T("Surprise celebrations at random times", "Праздники-сюрпризы в случайное время")
T("Swipe", "Затемнение")
T("Swipe opacity (percent)", "Непрозрачность затемнения (%)")
T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "Кнопкой под окном банка переключайтесь между штатными вкладками, объединённым банком, объединённым банком отряда и общими категориями. Общие категории включают доступные вкладки персонажа и отряда. «Управление вкладками банка» открывает покупки, внесение средств и настройки Blizzard. Каждая ячейка сохраняет своё действие предмета, а стопки банка никогда не объединяются; щелчок по предмету отряда сначала выбирает вкладку «Банк отряда» Blizzard, а возвращаемый предмет спрашивает подтверждение перед попаданием в банк отряда.")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Open Customize a bar below for layout and other options.", "Включайте и отключайте каждую панель здесь. Повторное включение восстанавливает прежний режим видимости. Откройте «Настроить панель» ниже для макета и других параметров.")
T("Switch the whole Skinning module here, or adjust Blizzard and Suite windows separately below.", "Включите или отключите весь модуль скинов здесь или настройте окна Blizzard и Suite по отдельности ниже.")
