T("Ten action bars plus stance and pet bars with free layout, paging, visibility rules and button styling. Key bindings keep using Blizzard's commands.", "Десять панелей команд, а также панели стоек и питомца со свободным макетом, листанием, правилами видимости и стилем кнопок. Назначения клавиш по-прежнему используют команды Blizzard.")
