T("That bar shows buffs.", "Эта панель показывает баффы.")
T("That bar shows cooldowns.", "Эта панель показывает восстановления.")
T("That changed since, so it cannot be undone.", "С тех пор это изменилось, поэтому отменить нельзя.")
T("That did not work.", "Не получилось.")
T("That macro name already exists", "Такое имя макроса уже существует")
T("The Great Vault is available only in Retail", "Великое хранилище доступно только в Retail")
T("The Mapko skin for Blizzard nameplates. Blizzard keeps health, threat, casts, auras, selection and click handling.", "Оформление Mapko для индикаторов Blizzard. Здоровье, угроза, заклинания, ауры, выбор и щелчки остаются под управлением Blizzard.")
T("The Suite Cooldown manager page (CDM) shows Blizzard's tracked cooldowns and buffs as bars you arrange and style freely.", "На странице «Менеджер времени восстановления» (CDM) в Suite отслеживаемые Blizzard перезарядки и положительные эффекты отображаются в виде полос, которые можно свободно размещать и оформлять.")
T("The Suite Minimap page styles the minimap itself: size, shape, border, zoom, buttons and info texts. MSUF's own minimap icon is under Miscellaneous.", "На странице «Мини-карта» в Suite настраиваются размер, форма, рамка, масштаб, кнопки и информационные надписи мини-карты. Значок самого MSUF на мини-карте находится в разделе «Разное».")
T("The Suite Nameplates page styles Blizzard's enemy and friendly nameplates. MSUF's aura filters only decide whether nameplate-only auras show on MSUF frames.", "На странице «Индикаторы имен» в Suite настраивается оформление индикаторов имен противников и союзников Blizzard. Фильтры аур MSUF определяют только то, будут ли ауры, предназначенные исключительно для индикаторов имен, показаны на рамках MSUF.")
T("The Suite draws its own tracker and hides Blizzard's while it runs. Entries are sorted into groups: the focused quest, campaign and important quests, quests ready to hand in, regular quests, world quests, nearby bonus objectives, scenario and delve steps, and tracked achievements. In a raid it can hide completely, only while a boss is engaged, or pause the regular list during any raid fight; the encounter view keeps running then. Quest symbols come as Suite letters or as Blizzard's icons, and the heading line can be switched off. The key binding Use tracked quest item uses the focused quest's item, else the first usable one, and picks a new item only outside combat. Left-click a group name to fold it or a quest to open its log entry; right-click for more actions.", "Suite рисует собственный список заданий и скрывает список Blizzard, пока работает. Записи сортируются по группам: задание в фокусе, задания кампании и важные задания, задания, готовые к сдаче, обычные задания, локальные задания, ближайшие дополнительные цели, этапы сценариев и вылазок, а также отслеживаемые достижения. В рейде список может скрываться полностью, только пока идёт бой с боссом, или приостанавливать обычный список в любом рейдовом бою; вид сражения при этом продолжает работать. Значки заданий — буквы Suite или значки Blizzard, а строку заголовка можно отключить. Привязка «Использовать предмет отслеживаемого задания» использует предмет задания в фокусе, иначе первый доступный, и выбирает новый предмет только вне боя. Щелчок левой кнопкой по названию группы сворачивает её, по заданию — открывает его запись в журнале; правый щелчок даёт другие действия.")
T("The Suite look gives Blizzard's dialogs a dark panel, and the Suite font sets their text font and size; each works alone, and without them dialogs keep Blizzard's look and fonts. A minimum height makes short dialogs taller once Blizzard has sized them; 0 keeps Blizzard's height. A custom position moves the first dialog and the ones Blizzard stacks below it; place it and set the height in MSUF Edit Mode.", "Оформление Suite даёт диалогам Blizzard тёмную панель, а шрифт Suite задаёт шрифт и размер их текста; каждое работает отдельно, а без них диалоги сохраняют вид и шрифты Blizzard. Минимальная высота делает короткие диалоги выше после того, как Blizzard задаст их размер; 0 оставляет высоту Blizzard. Своё положение перемещает первый диалог и те, что Blizzard ставит под ним; разместите его и задайте высоту в режиме редактирования MSUF.")
T("The Suite skin engine is unavailable.", "Движок скинов Suite недоступен.")
T("The chosen profile supplies all settings. Toggle which Suite modules are enabled in it.", "Выбранный профиль задает все настройки. Отметьте, какие модули Suite в нем включены.")
T("The class buff is included only when your character knows it. Enter self-buff spell IDs separated by spaces or commas. For a consumable, enter item ID:aura ID; separate pairs with commas. Up to 12 total reminders are shown. Weapon enchant items use the main-hand or off-hand enchant state.", "Бафф класса учитывается, только если ваш персонаж его знает. Введите ID заклинаний баффов на себя через пробел или запятую. Для расходуемого предмета введите ID предмета:ID ауры; пары разделяйте запятыми. Показывается не более 12 напоминаний. Предметы чар для оружия используют состояние чар правой или левой руки.")
T("The combined bag and reagent bag use a Suite panel with a distinct header, border, and accent line. Set background opacity to 0 for a transparent window; item slots stay visible.", "Общая сумка и сумка для реагентов используют панель Suite с отдельным заголовком, рамкой и акцентной линией. Установите непрозрачность фона 0 для прозрачного окна; ячейки предметов остаются видимыми.")
T("The combined bag setting is protected on this client", "Настройка общей сумки защищена в этом клиенте")
T("The cooldown manager is not loaded.", "Менеджер восстановления не загружен.")
T("The cooldown manager needs an update. Reload the interface.", "Менеджер восстановления нужно обновить. Перезагрузите интерфейс.")
T("The cooldown manager was reset: settings, spell lists and spell options.", "Менеджер восстановления сброшен: настройки, списки заклинаний и параметры заклинаний.")
T("The countdown turns to the warning color below this many seconds. All bars: the Text section's setting.", "Отсчет окрашивается цветом предупреждения, когда остается меньше указанного числа секунд. Все панели: настройка раздела «Текст».")
T("The dark sweep over the icon while it counts down.", "Темная заливка поверх значка во время отсчета.")
T("The default font follows MSUF Fonts while the default size follows Blizzard's chat size. Choose Blizzard chat font to keep its own face. Slug has no shadow.", "Шрифт по умолчанию следует шрифтам MSUF, а размер по умолчанию — размеру чата Blizzard. Выберите «Шрифт чата Blizzard», чтобы сохранить его начертание. У Slug нет тени.")
T("The dungeon's timer", "Таймер подземелья")
T("The global cooldown can leave the ring for a fixed circle of its own size and opacity, shown next to casts. Place it in MSUF Edit Mode; its button there works while this choice is on.", "Глобальное восстановление может покинуть кольцо и показываться в отдельном неподвижном круге со своими размером и непрозрачностью, рядом с заклинаниями. Разместите его в режиме редактирования MSUF; его кнопка там работает, пока этот выбор включен.")
T("The header shows the meter and fight. Its buttons change the meter and fight directly in the window.", "Заголовок показывает счетчик и бой. Его кнопки меняют счетчик и бой прямо в окне.")
T("The keystone notice remains local. The optional group announcement forwards only Blizzard's confirmed reset message immediately after your own reset request, while you are group leader. Failed attempts and resets by other players are not announced.", "Уведомление о ключе остаётся локальным. Необязательное сообщение группе передаёт только подтверждённое Blizzard сообщение о сбросе сразу после вашего запроса, пока вы руководите группой. Неудачные попытки и сбросы других игроков не объявляются.")
T("The macro builder is available only in Retail", "Построитель макросов доступен только в Retail.")
T("The macro exceeds the 255-character limit", "Макрос превышает ограничение в 255 символов.")
T("The map grows or shrinks to the chosen width and height while the pointer is over it, then returns to its normal size. A circular map keeps its height equal to its width.", "Пока курсор над картой, она увеличивается или уменьшается до выбранной ширины и высоты, затем возвращается к обычному размеру. Круглая карта сохраняет высоту равной ширине.")
T("The merchant's offers changed; nothing was bought.", "Товары торговца изменились; ничего не куплено.")
T("The merchant's whole stock in one scrolling list with prices, quality colors and item levels.", "Весь товар торговца в одном прокручиваемом списке с ценами, цветами качества и уровнями предметов.")
T("The minutes below", "Минуты ниже")
T("The mouse wheel zooms the map. Middle-click runs the chosen action; left and right clicks keep working as usual.", "Колесо мыши меняет масштаб карты. Средний клик выполняет выбранное действие; левый и правый клики работают как обычно.")
T("The native input box keeps autocomplete, links and chat commands.", "Стандартная строка ввода сохраняет автодополнение, ссылки и команды чата.")
T("The normal warning time", "Обычное время предупреждения")
T("The party table grows in steps: characters with build and score, then the combat figures of Blizzard's damage meter, then the loot seen in chat. Each character keeps its latest runs; open the newest here or with /msufruns and step through older ones. Deleting a run asks for a second click. The card can wait until you close the chest's loot window.", "Таблица группы растёт по ступеням: персонажи со сборкой и рейтингом, затем боевые показатели из измерителя урона Blizzard, затем добыча, замеченная в чате. Каждый персонаж хранит свои последние забеги; откройте самый новый здесь или командой /msufruns и листайте к более старым. Удаление забега требует второго щелчка. Карточка может подождать, пока вы не закроете окно добычи из сундука.")
T("The preview and every section below edit this bar. Shared custom groups start with a separate list for explicit spell, aura and item IDs; disabling sharing restores the existing per-specialization list.", "Предпросмотр и все разделы ниже изменяют эту панель. Общие пользовательские группы начинают с отдельного списка явно заданных ID заклинаний, аур и предметов; отключение общего режима восстанавливает прежний список специализации.")
T("The preview needs the cooldown manager.", "Для предпросмотра нужен менеджер восстановления.")
T("The quick switch above remembers this mode when you turn the bar off. Choose Never to keep it hidden.", "Быстрый переключатель выше запоминает этот режим, когда вы отключаете панель. Выберите «Никогда», чтобы держать ее скрытой.")
T("The settings you change most. Attach the bar to another bar or to your player frame to keep them together; the gap is the space between them. Center keeps the first cooldown icon in the middle and adds the next icons right, left, right, left. Visible buffs stay compact; on a horizontal mixed bar, player and target buffs grow outward from the center on one row.", "Самые часто изменяемые настройки. Прикрепите панель к другой панели или к фрейму игрока, чтобы держать их вместе; зазор — это расстояние между ними. «Центр» держит первый значок восстановления посередине и добавляет следующие справа, слева, справа, слева. Видимые баффы остаются компактными; на горизонтальной смешанной панели баффы игрока и цели растут наружу от центра в один ряд.")
T("The socket window is available only in Retail", "Окно сокета доступно только в Retail.")
T("The stack condition uses Glow at stacks and Stack comparison. Buff absence cannot drive a combat glow through the native aura-slot API.", "Условие использует порог свечения и сравнение суммирований. Отсутствие эффекта не может управлять свечением в бою через штатный API ячеек аур.")
T("These apply to every bar. The standalone assisted icon follows Blizzard's assisted combat highlight; enable that highlight in the game's Combat options. Its position is available in MSUF Edit Mode. Action bar presses show on cooldown icons only with the MSUF Suite action bars.", "Настройки применяются ко всем панелям. Отдельный значок следует подсветке помощи в бою Blizzard; включите её в настройках боя игры. Положение значка меняется в режиме редактирования MSUF. Нажатия кнопок панели команд показываются на значках восстановления только с панелями команд MSUF Suite.")
T("These apply to every bar:", "Применяется ко всем панелям:")
T("These choices apply to this spell on every bar and specialization.", "Эти параметры применяются к этому заклинанию на всех панелях и во всех специализациях.")
T("These settings apply to all bars until a bar uses its own style.", "Эти настройки применяются ко всем панелям, пока панель не использует свой стиль.")
T("Thick outline", "Толстый контур")
T("Thick outline + SLUG", "Толстый контур + SLUG")
T("Thick outline + shadow", "Толстый контур + тень")
T("Thin", "Тонкий")
T("Thin ring", "Тонкое кольцо")
T("This bar cannot be moved on its own right now.", "Эту панель сейчас нельзя переместить отдельно.")
T("This bar has no spells or items you added.", "На этой панели нет добавленных вами заклинаний или предметов.")
T("This bar has no spells yet. Click to add some.", "На этой панели пока нет заклинаний. Нажмите, чтобы добавить.")
T("This bar is full.", "Эта панель заполнена.")
T("This bar is off.", "Эта панель отключена.")
T("This bar sits on Blizzard's Essential bar, which your MSUF frames follow. Move it in Blizzard's Edit Mode.", "Эта панель находится на основной панели Blizzard, за которой следуют ваши фреймы MSUF. Перемещайте ее в режиме редактирования Blizzard.")
T("This bar takes the place of %s, which is off. Move that bar, or attach this one elsewhere.", "Эта панель занимает место панели «%s», которая отключена. Переместите ту панель или прикрепите эту в другое место.")
T("This bar's own options are not used by the %s type; the settings below apply to every bar.", "Собственные параметры этой панели не используются типом %s; настройки ниже применяются ко всем панелям.")
T("This category already holds 500 items. Remove one before adding another.", "В этой категории уже 500 предметов. Удалите один, прежде чем добавлять другой.")
T("This client has no combined bag setting", "В этом клиенте нет настройки общей сумки")
T("This client has not been identified", "Этот клиент не распознан")
T("This demon is not one you chose; summon another.", "Этот демон не из выбранных; призовите другого.")
T("This feature is available only in Retail", "Эта функция доступна только в Retail")
T("This finishes loading the selected Suite modules.", "Это завершит загрузку выбранных модулей Suite.")
T("This purchase cannot be refunded.", "Эту покупку нельзя вернуть.")
T("This slot contains %d; clicking uses this physical stack.", "В этой ячейке %d; щелчок использует именно эту стопку.")
T("Threat", "Угроза")
T("Threat lost / taking aggro", "Угроза потеряна / перехват агро")
T("Threat meter", "Измеритель угрозы")
T("Threat meter (Forever)", "Измеритель угрозы (Forever)")
T("Threat points", "Очки угрозы")
T("Threat warning", "Предупреждение об угрозе")
T("Three rows", "Три ряда")
