T("Tick every demon you want out; demons your character has not learned yet can be ticked too. A summoned demon you left unticked gets a notice, as long as one of your ticked demons can be summoned. Another look of a demon counts as that demon once you have summoned it in that look.", "Отметьте каждого демона, которого хотите видеть рядом; отмечать можно и демонов, которых персонаж ещё не изучил. Призванный неотмеченный демон получает уведомление, если можно призвать одного из отмеченных демонов. Другой облик демона считается этим демоном, как только вы призовёте его в этом облике.")
