T("Timestamps use Blizzard's chat setting across all chat windows. Copy is off by default; when enabled, move its button with X/Y, choose a message, then press Ctrl+C. The displayed timestamp is included when timestamps are on. The message tools leave the Combat Log alone (its own settings can add a timestamp to every line); its lines still wake the idle fade. Saved history belongs to this character.", "Метки времени используют настройку чата Blizzard во всех окнах чата. Копирование по умолчанию выключено; если его включить, переместите кнопку через X/Y, выберите сообщение и нажмите Ctrl+C. Отображаемая метка времени копируется, если метки времени включены. Инструменты сообщений не трогают журнал боя (его собственные настройки могут ставить метку времени на каждую строку); его строки всё же пробуждают затухание при бездействии. Сохранённая история принадлежит этому персонажу.")
