T("Turn off Show combat time to hide both the duration in every meter header and the separate floating timer. The two switches below let you show either one independently.", "Отключите «Показывать время боя», чтобы скрыть и длительность во всех заголовках счетчиков, и отдельный плавающий таймер. Два переключателя ниже позволяют показывать каждый из них независимо.")
T("Turn on \"%s\" to change this.", "Включите «%s», чтобы изменить это.")
T("Turn on Secondary stats in the MSUF Suite options to use the FPS readout.", "Включите вторичные характеристики в настройках MSUF Suite, чтобы пользоваться счетчиком кадров.")
