T("Tutorials and help overlays", "Обучение и справочные наложения")
T("Two rows", "Два ряда")
T("Type /keys or /msufkeys to see your own current keystone. Add party, raid or instance to share it in that channel. /keys group requests keys from group members running this Suite helper. The /keys alias is used only when another addon has not claimed it. Inside dungeons and raids Blizzard locks chat for addons; your key is then shown only to you.", "Введите /keys или /msufkeys, чтобы увидеть свой текущий эпохальный ключ. Для отправки в соответствующий канал добавьте буквальный аргумент party, raid или instance. Команда /keys group запрашивает ключи участников группы, использующих эту функцию Suite. Короткая команда /keys доступна, только если ее не занял другой аддон. В подземельях и рейдах Blizzard блокирует чат для аддонов; тогда ключ видите только вы.")
T("Type /msufguildprivacy or use the small ON/OFF button above the main chat window. Any chat window containing Guild or Officer is covered in full, including other channels in a mixed window. Click a cover to reveal the windows again. Messages keep arriving underneath.", "Введите /msufguildprivacy или воспользуйтесь маленькой кнопкой ВКЛ/ВЫКЛ над главным окном чата. Все окна чата, содержащие сообщения гильдии или офицеров, целиком закрываются ширмой, включая другие каналы в смешанном окне. Нажмите на ширму, чтобы снова открыть окно. Сообщения продолжают поступать под ней.")
T("Type /msufmacro to preview a mouseover ally, mouseover enemy or focus enemy macro. Enter a spell name or ID, then explicitly create a character macro outside combat. Drag it from /macro to your action bar.", "Введите /msufmacro, чтобы просмотреть макрос при наведении курсора мыши на союзника, врага или фокуса на враге. Введите имя или идентификатор заклинания, а затем явно создайте макрос персонажа вне боя. Перетащите его из /macro на панель действий.")
T("Type /msufraid to expand Blizzard's Raid Manager, /msufpull [1-60] for its native countdown, or /msufmark tank or /msufmark healer to mark one unambiguous party member. Optional automatic markers work only for one clear tank or healer in a five-player party, as leader or assistant. Existing and occupied markers are respected. Countdowns, markers and ready checks wait while Blizzard restricts them during combat, encounters and keystones; automatic markers try again afterwards.", "Введите /msufraid, чтобы открыть рейдовую панель Blizzard, /msufpull [1-60] для стандартного обратного отсчета или /msufmark tank либо /msufmark healer, чтобы поставить метку одному однозначно определенному члену группы. Автоматические метки работают только для одного танка или целителя в группе из пяти игроков, если вы лидер или помощник. Существующие и занятые метки сохраняются. Отсчеты, метки и проверки готовности ждут, пока Blizzard ограничивает их в бою, в схватках с боссами и в эпохальных ключах; автоматические метки повторяются после этого.")
T("Type /way x y for the current map or /way mapID x y. /msufway always works. The short /way alias is used only when no other addon owns it.", "Введите /way x y для текущей карты или /way mapID x y. /msufway всегда работает. Короткий псевдоним /way используется только в том случае, если он не принадлежит другому аддону.")
