T("Uses Blizzard's Sell All Junk action when a merchant opens, including its per-bag exclusions. Hold Shift while opening the merchant to skip selling. The optional chat line confirms the request, not completed sales.", "Использует действие Blizzard «Продать весь хлам» при открытии окна торговца, включая исключения для отдельных сумок. Удерживайте Shift при открытии торговца, чтобы пропустить продажу. Необязательная строка в чате подтверждает запрос, а не завершенную продажу.")
