T("When a Bloodlust-type buff from anyone in your group reaches you", "Когда на вас попадает эффект вроде Жажды крови от любого участника группы")
T("When a dungeon queue pops", "Когда появляется очередь в подземелье")
T("When a ready check starts outside combat and your mana as a healer is low, a short note shows how much you have; it turns red below half of your limit. Only your own mana is read.", "Когда вне боя начинается проверка готовности, а мана лекаря на исходе, короткая заметка показывает, сколько её осталось; ниже половины порога она становится красной. Читается только ваша собственная мана.")
T("When leaving", "При выходе")
T("When someone offers you a resurrection, its dialog gets a green frame, optionally with Blizzard's ready check sound, and its accept button can get a green frame of its own. Accepting stays your click.", "Когда вам предлагают воскрешение, диалог получает зелёную рамку, по желанию со звуком проверки готовности Blizzard, а кнопка принятия может получить собственную зелёную рамку. Принять по-прежнему нужно своим щелчком.")
T("When the key ends", "Когда ключ завершён")
T("When the native group listing panel closes with applications still active, show their count in your own chat. Your applications remain active and no group chat is sent.", "Если вы закрываете стандартную панель поиска групп с активными заявками, их количество отображается в вашем чате. Заявки остаются активными; сообщения в групповой чат не отправляются.")
T("When the selected bar appears", "Когда появляется выбранная панель")
T("When this bar shows, and how far it fades out of combat. Tooltips show a spell when you hover its icon. This page and MSUF Edit Mode always show every bar.", "Когда эта панель показывается и насколько она затухает вне боя. Подсказки показывают заклинание при наведении на его значок. Эта страница и режим редактирования MSUF всегда показывают все панели.")
T("When to remind", "Когда напоминать")
T("When to show", "Когда показывать")
T("When you earn an achievement", "При получении достижения")
T("When you gain a level", "При получении уровня")
T("When you or your pet cast Bloodlust or a similar haste spell", "Когда вы или ваш питомец применяете Жажду крови или похожее заклинание скорости")
T("Where are the Suite minimap settings?", "Где находятся настройки мини-карты Suite?")
T("Where are the nameplate settings?", "Где находятся настройки индикаторов имен?")
T("Where is the cooldown manager?", "Где находится менеджер времени восстановления?")
T("Where the buff or debuff is looked for. Automatic: harmful spells on your target, all others on you.", "Где ищется бафф или дебафф. «Автоматически»: вредоносные заклинания — на вашей цели, остальные — на вас.")
T("Where to show recent actions", "Где показывать недавние действия")
T("Which number is drawn on top when both show.", "Какое число рисуется сверху, когда показаны оба.")
T("Which numbers show, which one is drawn on top, and their size and place. Single spells can differ: click them in the preview. The font settings below apply to every bar; Slug has no shadow.", "Какие числа показываются, какое рисуется сверху, их размер и место. Отдельные заклинания могут отличаться: нажмите их в предпросмотре. Настройки шрифта ниже применяются ко всем панелям; у Slug нет тени.")
T("While DataTexts and this choice are enabled, MSUF remembers this character's gold at login and after money changes. Hover a Gold or Session gold DataText to see the last known account total and up to eight other characters. No background scans are used.", "Пока тексты данных и эта настройка включены, MSUF запоминает золото персонажа при входе и изменении количества денег. Наведите курсор на текст «Золото» или «Золото за сеанс», чтобы увидеть последний известный итог учётной записи и до восьми других персонажей. Фоновое сканирование не используется.")
T("While DataTexts is active, hide Blizzard's backpack and bag slots. A Bag space DataText opens the native bags when clicked. Turn this off to restore the Blizzard buttons.", "Пока инфотексты активны, рюкзак и ячейки сумок Blizzard скрыты. Инфотекст «Место в сумках» открывает стандартные сумки по клику. Отключите, чтобы вернуть кнопки Blizzard.")
T("While a key runs, each defeated boss shows how far ahead or behind you are: against the best time you ever had on that boss, or against the boss times of your fastest completed run, at this keystone level or at any. Only runs this character completed count. With target times on, bosses still alive show the time to beat.", "Во время ключа каждый побеждённый босс показывает, насколько вы впереди или позади: относительно вашего лучшего времени на этом боссе или времени боссов в самом быстром завершённом забеге, на этом уровне ключа или на любом. Учитываются только забеги, завершённые этим персонажем. С целевым временем живые боссы показывают время, которое нужно побить.")
T("While the buff of this spell lasts, the icon shows its duration and stacks instead of the cooldown.", "Пока действует бафф этого заклинания, значок показывает его длительность и стаки вместо восстановления.")
