T("Windows update from the client's own combat data: every event outside combat, and at the chosen interval during combat.", "Окна обновляются по собственным боевым данным клиента: вне боя — при каждом событии, в бою — с выбранным интервалом.")
T("WoW Forever only. Lists your group's threat on the watched enemy from Blizzard's threat data, highest first; for a friendly target, its enemy is used. Values the game keeps hidden are left out. Turn the mouse wheel over the window when more members are listed than rows fit. The red mark shows where you would take aggro, which is not the point where you match the tank. The meter repaints at most five times a second and reads no combat log.", "Только WoW Forever. Показывает угрозу вашей группы по отслеживаемому врагу из данных Blizzard, по убыванию; для дружественной цели используется ее враг. Скрытые игрой значения не показываются. Прокручивайте колесо мыши над окном, если участников больше, чем строк. Красная отметка показывает, где вы сорвете агро; это не точка, где вы сравняетесь с танком. Измеритель обновляется не чаще пяти раз в секунду и не читает журнал боя.")
